<?php

declare(strict_types=1);

namespace Reshapify\SendSeven\Generator;

/**
 * Writes generated files, and removes generated files that are no longer
 * produced. Files without the marker are hand-written and never touched.
 */
final class Writer
{
    public const string MARKER = '@generated by bin/generate';

    /** @var array<string, true> */
    private array $written = [];

    public function __construct(private readonly string $root) {}

    /**
     * The marker as an HTML comment, for Markdown and text files.
     */
    public static function markdownHeader(): string
    {
        return '<!-- This file is '.self::MARKER." from SendSeven's OpenAPI spec. Do not edit it: change the generator or openapi/patches, then regenerate. -->\n\n";
    }

    public static function header(): string
    {
        return '// This file is '.self::MARKER." from SendSeven's OpenAPI spec. Do not edit it:\n// change the generator or openapi/patches, then regenerate.\n\n";
    }

    public function write(string $relativePath, string $contents): void
    {
        $file = $this->root.'/'.$relativePath;

        if (is_file($file) && ! str_contains((string) file_get_contents($file), self::MARKER)) {
            fwrite(STDERR, "Skipped {$relativePath}: hand-written.\n");

            return;
        }

        if (! is_dir(dirname($file))) {
            mkdir(dirname($file), 0755, true);
        }

        // On case-insensitive filesystems a rename that only changes case
        // would keep the old name; remove the old file first.
        foreach (glob(dirname($file).'/*') ?: [] as $existing) {
            if (strcasecmp($existing, $file) === 0 && $existing !== $file) {
                unlink($existing);
            }
        }

        file_put_contents($file, $contents);
        $this->written[strtolower($file)] = true;
    }

    /**
     * JSON files can't carry a comment, so the marker goes in a "_generated" key.
     *
     * @param  array<string, mixed>  $data
     */
    public function writeJson(string $relativePath, array $data): void
    {
        $this->write($relativePath, json_encode(['_generated' => self::MARKER, ...$data], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)."\n");
    }

    /**
     * Delete generated files in the directories that weren't written this run.
     *
     * @param  list<string>  $directories  relative to the root
     */
    public function prune(array $directories): int
    {
        $removed = 0;

        foreach ($directories as $directory) {
            foreach (glob($this->root.'/'.$directory.'/*.php') ?: [] as $file) {
                if (! isset($this->written[strtolower($file)]) && str_contains((string) file_get_contents($file), self::MARKER)) {
                    unlink($file);
                    $removed++;
                }
            }
        }

        return $removed;
    }

    public function count(): int
    {
        return count($this->written);
    }
}
